#!/usr/bin/env bash
# ==============================================================================
# Script: undo_compress_logs.sh
# Description: Pure Bash-native tool to revert log compression operations
#              recorded in a TSV undo manifest generated by compress_logs.sh.
# Dependencies: bash, coreutils (gzip, unzip, touch, stat, rm, mkdir)
#               Zero Python, zero jq, zero external scripting dependencies.
# Compatible with: Ubuntu, SUSE (SLES/openSUSE), Debian, RHEL/CentOS, Rocky Linux
# ==============================================================================

set -o pipefail

# -----------------------------
# Color Codes for Output
# -----------------------------
CYAN='\033[0;36m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
GRAY='\033[0;90m'
NC='\033[0m'

# -----------------------------
# Default Parameter Values
# -----------------------------
MANIFEST_PATH=""
KEEP_ARCHIVE=false
OVERWRITE_EXISTING=false
DRY_RUN=false
SKIP_ROOT_CHECK=false

# -----------------------------
# Help / Usage Function
# -----------------------------
show_help() {
    cat << 'EOF'
Usage: undo_compress_logs.sh -m <MANIFEST_PATH> [OPTIONS]

Reverts log compression operations recorded in a TSV undo manifest.
100% Bash-native: zero python or jq requirements.

Options:
  -m, --manifest PATH      Path to the TSV undo manifest file (.manifest or .log) (Required).
  --keep-archive           Keep archive files (.gz/.zip) after restoring original files.
  --overwrite              Overwrite existing uncompressed files if present.
  -n, --dry-run            Simulate restoration without modifying or deleting files.
  --skip-root-check        Bypass root privilege check.
  -h, --help               Display this help message and exit.

Examples:
  # Revert compression recorded in a manifest:
  sudo ./undo_compress_logs.sh -m ./compress_manifest_20261126_120000.manifest

  # Dry-run to preview what will be restored:
  sudo ./undo_compress_logs.sh -m ./compress_manifest_20261126_120000.manifest -n

  # Restore original files but preserve the archives:
  sudo ./undo_compress_logs.sh -m ./compress_manifest_20261126_120000.manifest --keep-archive
EOF
}

# -----------------------------
# Parse Command Line Arguments
# -----------------------------
while [[ $# -gt 0 ]]; do
    case "$1" in
        -m|--manifest|--manifest-path|--log-path)
            MANIFEST_PATH="$2"
            shift 2
            ;;
        --keep-archive|--keep-zip)
            KEEP_ARCHIVE=true
            shift
            ;;
        --overwrite|--overwrite-existing)
            OVERWRITE_EXISTING=true
            shift
            ;;
        -n|--dry-run)
            DRY_RUN=true
            shift
            ;;
        --skip-root-check)
            SKIP_ROOT_CHECK=true
            shift
            ;;
        -h|--help)
            show_help
            exit 0
            ;;
        *)
            echo -e "${RED}Error: Unknown option '$1'${NC}" >&2
            echo "Use -h or --help for usage details." >&2
            exit 1
            ;;
    esac
done

if [ -z "$MANIFEST_PATH" ]; then
    echo -e "${RED}Error: Manifest file path is required. Use -m or --manifest <path>.${NC}" >&2
    exit 1
fi

if [ ! -f "$MANIFEST_PATH" ]; then
    echo -e "${RED}Error: Manifest file not found at '$MANIFEST_PATH'${NC}" >&2
    exit 1
fi

if [ "$SKIP_ROOT_CHECK" = false ] && [ "$EUID" -ne 0 ]; then
    echo -e "${RED}Error: Root privileges required to restore system log files.${NC}" >&2
    echo -e "${YELLOW}Please re-run with 'sudo $0 ...' or use '--skip-root-check'.${NC}" >&2
    exit 1
fi

# -----------------------------
# Read Manifest Header Information (Pure Bash)
# -----------------------------
RUN_ID="N/A"
HOSTNAME_VAL="N/A"
START_TIME="N/A"
ARCHIVE_FORMAT="gz"

while IFS= read -r line; do
    [[ "$line" != \#* ]] && continue
    if [[ "$line" =~ ^#[[:space:]]*RunId:[[:space:]]*(.*) ]]; then
        RUN_ID="${BASH_REMATCH[1]}"
    elif [[ "$line" =~ ^#[[:space:]]*Hostname:[[:space:]]*(.*) ]]; then
        HOSTNAME_VAL="${BASH_REMATCH[1]}"
    elif [[ "$line" =~ ^#[[:space:]]*StartTime:[[:space:]]*(.*) ]]; then
        START_TIME="${BASH_REMATCH[1]}"
    elif [[ "$line" =~ ^#[[:space:]]*ArchiveFormat:[[:space:]]*(.*) ]]; then
        ARCHIVE_FORMAT="${BASH_REMATCH[1]}"
    fi
done < "$MANIFEST_PATH"

echo -e "${CYAN}==========================================================${NC}"
echo -e "${CYAN} Undo Log & Dump File Compression Tool (Bash-Native)${NC}"
echo -e " Manifest File     : $MANIFEST_PATH"
echo -e " Run ID            : ${GRAY}$RUN_ID${NC}"
echo -e " Original Host     : ${GRAY}$HOSTNAME_VAL${NC}"
echo -e " Original Run Time : ${GRAY}$START_TIME${NC}"
echo -e " Keep Archives     : $KEEP_ARCHIVE"
echo -e " Overwrite Existing: $OVERWRITE_EXISTING"
if [ "$DRY_RUN" = true ]; then
    echo -e " Dry Run Mode      : ${YELLOW}Enabled (Simulate only, no changes)${NC}"
fi
echo -e "${CYAN}==========================================================${NC}"

# -----------------------------
# Process Operations (Pure Bash TSV Stream)
# -----------------------------
OP_INDEX=0
RESTORED_COUNT=0
REMOVED_ARCHIVE_COUNT=0
SKIPPED_COUNT=0
FAILED_COUNT=0
PURGED_SKIPPED_COUNT=0

while IFS=$'\t' read -r action status orig_path orig_dir orig_mtime arc_path arc_name orig_deleted note || [ -n "$action" ]; do
    # Skip empty or comment lines
    [[ -z "$action" || "$action" == \#* ]] && continue

    (( OP_INDEX++ ))

    # Only process successful compress operations
    if [ "$action" != "COMPRESS" ] || [ "$status" != "SUCCESS" ]; then
        if [ "$action" == "PURGE" ]; then
            echo -e "${GRAY}[Note] Skipped Purge record (#$OP_INDEX) - permanently purged archives cannot be undone.${NC}"
            (( PURGED_SKIPPED_COUNT++ ))
        fi
        continue
    fi

    echo -ne "\n${CYAN}[Operation #$OP_INDEX]${NC} $orig_path ... "

    # Case 1: Original file was deleted -> extract archive back to original path
    if [ "$orig_deleted" = "1" ] || [ "$orig_deleted" = "true" ]; then
        if [ ! -f "$arc_path" ]; then
            echo -e "${RED}FAILED: Archive '$arc_path' not found. Cannot restore.${NC}"
            (( FAILED_COUNT++ ))
            continue
        fi

        if [ -f "$orig_path" ] && [ "$OVERWRITE_EXISTING" = false ]; then
            echo -e "${YELLOW}SKIPPED: Target uncompressed file already exists. Use --overwrite to replace.${NC}"
            (( SKIPPED_COUNT++ ))
            continue
        fi

        if [ "$DRY_RUN" = true ]; then
            echo -e "${GREEN}[WhatIf] Would restore '$orig_path' from '$arc_name'$(if [ "$KEEP_ARCHIVE" = false ]; then echo " and remove archive"; fi)${NC}"
            (( RESTORED_COUNT++ ))
            continue
        fi

        mkdir -p "$orig_dir" 2>/dev/null
        restored=false

        if [[ "$arc_name" == *.gz ]]; then
            if gzip -dc "$arc_path" > "$orig_path" 2>/dev/null; then
                restored=true
            fi
        elif [[ "$arc_name" == *.zip ]]; then
            if unzip -q -o "$arc_path" -d "$orig_dir" 2>/dev/null; then
                restored=true
            fi
        fi

        if [ "$restored" = true ] && [ -f "$orig_path" ]; then
            # Restore original file modification timestamp using epoch
            if [ -n "$orig_mtime" ] && [ "$orig_mtime" != "-" ]; then
                touch -d "@$orig_mtime" "$orig_path" 2>/dev/null || true
            fi

            echo -e "${GREEN}Restored: $orig_path${NC}"
            (( RESTORED_COUNT++ ))

            if [ "$KEEP_ARCHIVE" = false ]; then
                rm -f "$arc_path" 2>/dev/null
                echo -e "  ${GRAY}└─ Removed archive: $arc_name${NC}"
                (( REMOVED_ARCHIVE_COUNT++ ))
            fi
        else
            echo -e "${RED}FAILED: Decompression failed for '$arc_path'${NC}"
            (( FAILED_COUNT++ ))
        fi

    # Case 2: Original file was preserved (delete original was false) -> simply remove redundant archive
    else
        if [ -f "$arc_path" ]; then
            if [ "$KEEP_ARCHIVE" = false ]; then
                if [ "$DRY_RUN" = true ]; then
                    echo -e "${GREEN}[WhatIf] Would remove redundant archive '$arc_name' (original file is intact)${NC}"
                    (( REMOVED_ARCHIVE_COUNT++ ))
                else
                    rm -f "$arc_path" 2>/dev/null
                    echo -e "${GREEN}Removed archive: $arc_name (original file already intact)${NC}"
                    (( REMOVED_ARCHIVE_COUNT++ ))
                fi
            else
                echo -e "${GRAY}Original file intact; --keep-archive specified, leaving archive in place.${NC}"
                (( SKIPPED_COUNT++ ))
            fi
        else
            echo -e "${GRAY}Original file intact and archive '$arc_name' is already gone.${NC}"
            (( SKIPPED_COUNT++ ))
        fi
    fi
done < "$MANIFEST_PATH"

# -----------------------------
# Summary Report
# -----------------------------
echo -e "\n${CYAN}======================= SUMMARY ==========================${NC}"
echo -e "Total Operations Evaluated   : $OP_INDEX"
echo -e "Original Files Restored      : ${GREEN}$RESTORED_COUNT${NC}"
echo -e "Archives Removed             : ${GREEN}$REMOVED_ARCHIVE_COUNT${NC}"
echo -e "Skipped                      : $(if (( SKIPPED_COUNT > 0 )); then echo -e "${YELLOW}$SKIPPED_COUNT${NC}"; else echo -e "$SKIPPED_COUNT"; fi)"
echo -e "Non-Reversible (e.g. Purged) : ${GRAY}$PURGED_SKIPPED_COUNT${NC}"
echo -e "Failed Operations            : $(if (( FAILED_COUNT > 0 )); then echo -e "${RED}$FAILED_COUNT${NC}"; else echo -e "$FAILED_COUNT"; fi)"
echo -e "${CYAN}==========================================================${NC}"
